+// initBridgeConflict names why the bridge README cannot be added without replacing or
+// bypassing something that exists in the copy; it is "" when the path is free.
+func initBridgeConflict(clone string) string {
+	parts := strings.Split(initStepsReadmePath, "/")
+	for i := range parts {
+		p := strings.Join(parts[:i+1], "/")
+		full := filepath.Join(clone, p)
+		if i == len(parts)-1 {
+			_, err := os.Lstat(full)
+			switch {
+			case err == nil:
+				return p + " already exists, so the Cucumber bridge was left out"
+			case os.IsNotExist(err):
+				return ""
+			}
+			return fmt.Sprintf("%s cannot be used (%v), so the Cucumber bridge was left out", p, err)
+		}
+		st, err := os.Stat(full)
+		if os.IsNotExist(err) {
+			if _, lerr := os.Lstat(full); lerr != nil {
+				return ""
+			}
+		} else if err == nil && st.IsDir() {
+			continue
+		}
+		return p + " is not a usable directory, so the Cucumber bridge was left out"
+	}
+	return ""
+}
+
 func initAddBridge(ctx context.Context, s *sys.Session, in InitInput, clone string, res *initResult) error {
+	if reason := initBridgeConflict(clone); reason != "" {
+		res.how = "not configured: " + reason
+		return nil
+	}
 	if err := os.MkdirAll(filepath.Join(clone, "features/steps"), 0o755); err != nil {
 		return err

